const id = $json.body.campaign_id;
const uuidRe = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
if (typeof id !== 'string' || !uuidRe.test(id)) {
  throw new Error('campaign_id missing or not a valid UUID: ' + JSON.stringify(id));
}
return [{ json: { campaign_id: id } }];
